import{_ as e,o as d,c as r,ai as a}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"主流 Agent 厂商一览","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/basics/agent-landscape.md","filePath":"ai/dev/basics/agent-landscape.md"}'),o={name:"ai/dev/basics/agent-landscape.md"};function n(h,t,l,s,i,c){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="主流-agent-厂商一览" tabindex="-1">主流 Agent 厂商一览 <a class="header-anchor" href="#主流-agent-厂商一览" aria-label="Permalink to “主流 Agent 厂商一览”">​</a></h1><blockquote><p><strong>维护约定</strong>：国外只盯几家标杆；国内产品名变了改表即可。底层模型见 <a href="./model-landscape.html">主流大模型厂商一览</a>；概念见 <a href="/my-vitepress-site/ai/dev/agent/agent-overview.html">Agent 是什么</a>。</p></blockquote><p>一页地图：先分清 <strong>Code Agent</strong>（改代码）和 <strong>Worker Agent</strong>（办任务）。国外列标杆，国内列常用可触达产品。</p><h2 id="国外-标杆" tabindex="-1">国外（标杆） <a class="header-anchor" href="#国外-标杆" aria-label="Permalink to “国外（标杆）”">​</a></h2><table tabindex="0"><thead><tr><th>厂商 / 出品方</th><th>代表产品</th><th>形态</th><th>类型</th><th>是否开源</th><th>官网</th></tr></thead><tbody><tr><td>Anysphere</td><td>Cursor（Agent / Cloud Agent）</td><td>AI IDE · CLI · 云端</td><td>Code</td><td>闭源</td><td><a href="https://cursor.com" target="_blank" rel="noreferrer">cursor.com</a></td></tr><tr><td>Anthropic</td><td>Claude Code</td><td>终端为主 · IDE 协同</td><td>Code</td><td>闭源</td><td><a href="https://docs.anthropic.com/en/docs/claude-code" target="_blank" rel="noreferrer">文档</a> · <a href="https://claude.ai" target="_blank" rel="noreferrer">claude.ai</a></td></tr><tr><td>OpenAI</td><td>Codex · Operator</td><td>终端/云端改代码 · 浏览器办事</td><td>Code + Worker</td><td>闭源</td><td><a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">Codex</a> · <a href="https://openai.com" target="_blank" rel="noreferrer">openai.com</a></td></tr><tr><td>Cognition</td><td>Devin · Windsurf</td><td>云端委托 · AI IDE</td><td>Code</td><td>闭源</td><td><a href="https://devin.ai" target="_blank" rel="noreferrer">devin.ai</a> · <a href="https://windsurf.com" target="_blank" rel="noreferrer">windsurf.com</a></td></tr></tbody></table><h2 id="国内" tabindex="-1">国内 <a class="header-anchor" href="#国内" aria-label="Permalink to “国内”">​</a></h2><table tabindex="0"><thead><tr><th>厂商 / 出品方</th><th>代表产品</th><th>形态</th><th>类型</th><th>是否开源</th><th>官网</th></tr></thead><tbody><tr><td>腾讯</td><td>CodeBuddy · WorkBuddy</td><td>IDE/插件/CLI · 办公桌面 Agent</td><td>Code + Worker</td><td>闭源</td><td><a href="https://www.workbuddy.cn/docs/ide/" target="_blank" rel="noreferrer">CodeBuddy</a> · <a href="https://cloud.tencent.com.cn/product/workbuddy" target="_blank" rel="noreferrer">WorkBuddy</a></td></tr><tr><td>小米</td><td>MiMo Code</td><td>终端 Code Agent（基于 OpenCode）</td><td>Code</td><td>开源</td><td><a href="https://mimo.mi.com/docs/zh-CN/news/latest/mimocode" target="_blank" rel="noreferrer">MiMo Code</a> · <a href="https://github.com/XiaomiMiMo/MiMo-Code" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td>阿里</td><td>通义灵码</td><td>IDE 插件 · 企业研发流</td><td>Code</td><td>闭源</td><td><a href="https://lingma.aliyun.com" target="_blank" rel="noreferrer">lingma.aliyun.com</a></td></tr><tr><td>字节</td><td>豆包 / 火山 Agent 能力</td><td>应用内助手 · 研发与办公</td><td>混合</td><td>闭源</td><td><a href="https://www.doubao.com" target="_blank" rel="noreferrer">豆包</a> · <a href="https://www.volcengine.com" target="_blank" rel="noreferrer">火山</a></td></tr><tr><td>月之暗面</td><td>Kimi（含编程 / 长程任务）</td><td>网页 · API</td><td>混合</td><td>混合</td><td><a href="https://www.moonshot.cn" target="_blank" rel="noreferrer">moonshot.cn</a></td></tr><tr><td>智谱</td><td>GLM Coding / ZCode 等</td><td>IDE · API · 编程 Agent</td><td>Code</td><td>混合</td><td><a href="https://www.zhipuai.cn" target="_blank" rel="noreferrer">zhipuai.cn</a> · <a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">开放平台</a></td></tr><tr><td>百度</td><td>文心 / Comate 等</td><td>IDE · 应用助手</td><td>混合</td><td>闭源</td><td><a href="https://comate.baidu.com" target="_blank" rel="noreferrer">comate.baidu.com</a></td></tr><tr><td>DeepSeek</td><td>模型 API + 各端 Agent 接入</td><td>多通过 IDE/终端接模型当 Agent 脑</td><td>Code（偏底座）</td><td>混合</td><td><a href="https://www.deepseek.com" target="_blank" rel="noreferrer">deepseek.com</a></td></tr></tbody></table><p><strong>国内怎么认</strong>：腾讯拆成两条——<strong>CodeBuddy 写代码</strong>，<strong>WorkBuddy 办办公活</strong>（Worker），别混成一个产品。小米 <strong>MiMo Code</strong> 是终端编程 Agent，能拍上「国内 Code」这一栏，但更偏新开源探索，不和 Cursor / Claude Code 当同一成熟度去比。</p><p><strong>类型</strong>：<code>Code</code> = 读仓改码跑命令；<code>Worker</code> = 浏览器/文件/业务交付；<code>混合</code> = 两边都沾。</p><p><strong>形态</strong>：AI IDE / 终端 / 云端委托 / 网页应用——同一厂可多形态并存。</p><hr><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to “怎么用”">​</a></h2><ol><li>日常写代码 → 国外先看 <strong>Cursor</strong>；要终端深改再看 <strong>Claude Code / Codex</strong>。</li><li>丢任务异步出活 → <strong>Devin</strong>（国外）或国内各厂云端/应用内 Agent。</li><li>办事、点网页 → 国外看 <strong>Operator</strong>；国内优先看各厂应用内助手是否够用。</li><li>选模型底座仍回 <a href="./model-landscape.html">主流大模型厂商一览</a>。</li></ol>',13)])])}const f=e(o,[["render",n]]);export{p as __pageData,f as default};
